; --- PyMCU AVR Math Runtime ---
; -----------------------------------------------------------------------------
; PyMCU AVR Math Runtime
; -----------------------------------------------------------------------------
;
; __div32: Unsigned 32-bit Division
;   Input:  R23:R22:R25:R24 (Dividend, MSB..LSB), R21:R20:R19:R18 (Divisor)
;   Output: R23:R22:R25:R24 (Quotient)
;   Clobbers: R26:R27:R30:R31 (X, Z -- remainder), R16 (loop counter)
;
; Register layout (byte positions, LSB first):
;   byte0 = R24 (dividend / quotient LSB)
;   byte1 = R25
;   byte2 = R22
;   byte3 = R23 (dividend / quotient MSB)
;   divisor LSB = R18, byte1 = R19, byte2 = R20, MSB = R21
;   remainder LSB = R26, byte1 = R27, byte2 = R30, MSB = R31 (X:Z, local)
;
; Algorithm: Non-restoring bit-by-bit long division (33 iterations).
;
; Nothing here is PUSH/POP'd. R16 and X/Z (R26, R27, R30, R31) are all in the
; caller-saved set PyMCU's own codegen already treats as call-clobbered (see
; AvrCodeGen's ISR context save and its X-staging comment) -- the same set the
; hand-written pulse_in helpers in hal/avr/gpio/atmega328p.py already clobber
; without saving. The remainder used to live in R4-R7, which sit in the R2-R15
; named-variable home pool and ARE callee-saved, so every call paid for five
; PUSH/POP pairs (10 bytes, ~40 cycles) to protect state nothing but this
; routine's own two callers (below) ever wrote. Moving the remainder to X:Z
; removes the save entirely; PyMCU/PyMCU#408 has the measurement.
;
; div32s.S's __divs32/__mods32 build on __div32_core and were updated to the
; same convention; they still push/pop R8:R9 (and R10:R13 for __mods32),
; which hold sign flags and the original divisor, unrelated to the remainder.
;
; The SIGNED floor entry points __divs32 / __mods32 live in div32s.S and build on
; __div32_core below. They are a separate file because the build driver splices
; whole files: while they shared this one, a program doing a single unsigned
; 32-bit division still carried all 226 bytes of them.
;
; __mod32 lives in mod32.S for the same reason (PyMCU/PyMCU#408): a program
; calling only __div32 does not carry __mod32's own wrapper, though both still
; share this file's __div32_core (the build driver pulls div32.S in either way).
; -----------------------------------------------------------------------------

; __div32_core: shared inner loop used by __div32, __mod32, __divs32 and __mods32.
;   Pre-condition: R26:R27:R30:R31 = 0 (remainder), R16 = 33 (counter).
;   Post-condition: R23:R22:R25:R24 = Quotient, R31:R30:R27:R26 = Remainder.
;   Does NOT save/restore any registers.
__div32_core:
__div32_core_loop:
    rol r24             ; Shift dividend left (LSB first carries out MSB)
    rol r25
    rol r22
    rol r23
    dec r16
    breq __div32_core_done
    rol r26             ; Shift remainder left, incoming dividend MSB in Carry
    rol r27
    rol r30
    rol r31
    sub r26, r18        ; Remainder -= Divisor
    sbc r27, r19
    sbc r30, r20
    sbc r31, r21
    brcc __div32_core_next  ; No borrow => remainder >= divisor
    add r26, r18        ; Restore remainder
    adc r27, r19
    adc r30, r20
    adc r31, r21
    clc                 ; Quotient bit = 0
    rjmp __div32_core_loop
__div32_core_next:
    sec                 ; Quotient bit = 1
    rjmp __div32_core_loop
__div32_core_done:
    ret

__div32:
    clr r26
    clr r27
    clr r30
    clr r31
    ldi r16, 33
    rcall __div32_core
    ret

; -----------------------------------------------------------------------------
; PyMCU AVR Math Runtime -- unsigned 32-bit modulo
; -----------------------------------------------------------------------------
;
; Split out of div32.S (PyMCU/PyMCU#408) so that a program calling only __div32
; does not carry __mod32's own wrapper too. The build driver splices whole
; files and the linker cannot drop what it never saw as a separate section, so
; the two used to be paid for together whichever one a program actually
; called -- the same shape div32s.S's header already documents for the signed
; entry points.
;
; Depends on __div32_core, which lives in div32.S: the driver pulls both files
; in whenever __mod32 is referenced.
; -----------------------------------------------------------------------------

; __mod32: Unsigned 32-bit Modulo
;   Input:  R23:R22:R25:R24 (Dividend), R21:R20:R19:R18 (Divisor)
;   Output: R23:R22:R25:R24 (Remainder)
;   Clobbers: R26:R27:R30:R31 (X, Z -- intermediate quotient), R16 (loop counter)
; Nothing is PUSH/POP'd: see div32.S's header for why X, Z and R16 need no save.
__mod32:
    clr r26
    clr r27
    clr r30
    clr r31
    ldi r16, 33
    rcall __div32_core
    mov r24, r26        ; Move remainder to result registers
    mov r25, r27
    mov r22, r30
    mov r23, r31
    ret

; -----------------------------------------------------------------------------
; PyMCU AVR Math Runtime
; -----------------------------------------------------------------------------
;
; __div8: Unsigned 8-bit Division
;   Input:  R24 (Dividend), R18 (Divisor)
;   Output: R24 (Quotient), R25 (Remainder)
;   Clobbers: R25
;
; __mod8: Unsigned 8-bit Modulo
;   Input:  R24 (Dividend), R18 (Divisor)
;   Output: R24 (Remainder)
;   Clobbers: R25
;
; -----------------------------------------------------------------------------

__div8:
    push r16
    ldi r16, 8      ; 8 iterations: one per dividend bit
    clr r25         ; Remainder = 0
    clc             ; Clear carry

__div8_loop:
    rol r24         ; Shift dividend left, MSB into Carry
    rol r25         ; Shift remainder left, Carry into LSB
    brcs __div8_sub ; Remainder overflowed (>= 256) -> must subtract
    cp r25, r18     ; Compare Remainder with Divisor
    brcs __div8_next; Remainder < Divisor: quotient bit = 0

__div8_sub:
    sub r25, r18    ; Remainder -= Divisor
    sec             ; Quotient bit = 1
    rjmp __div8_dec

__div8_next:
    clc             ; Quotient bit = 0

__div8_dec:
    dec r16
    brne __div8_loop

    rol r24         ; Final ROL shifts last quotient bit into R24

    pop r16
    ret

__mod8:
    rcall __div8
    mov r24, r25    ; Move remainder to result register
    ret

; -----------------------------------------------------------------------------
; __divs8 / __mods8: SIGNED 8-bit floor division and modulo (Python semantics).
;   Input:  R24 (Dividend a), R18 (Divisor b)   -- both signed
;   Output: __divs8 -> R24 = floor(a/b)
;           __mods8 -> R24 = a - b*floor(a/b)   (remainder takes the sign of b)
;   Net clobber: R24, R25 (same as __div8; R16/R17/R19 are push/pop-restored).
;
; Strategy: divide the magnitudes with the unsigned core, give the truncating
; quotient/remainder their signs, then apply the single Python floor correction
; (when the signs differ and the remainder is non-zero: q -= 1; r += b).
; -----------------------------------------------------------------------------
__divmods8:
    push r16
    push r17
    push r19
    mov  r19, r24       ; r19 = original a (sign of dividend)
    mov  r17, r18       ; r17 = original b (sign + floor add)
    sbrc r24, 7
    neg  r24            ; |a|
    sbrc r18, 7
    neg  r18            ; |b|
    rcall __div8        ; R24 = |a|/|b| (uq), R25 = |a|%|b| (ur); R18 preserved
    sbrc r19, 7
    neg  r25            ; truncating remainder takes the sign of a
    mov  r16, r19
    eor  r16, r17       ; r16 bit7 = 1 when signs differ (quotient is negative)
    sbrc r16, 7
    neg  r24            ; truncating quotient sign
    sbrs r16, 7
    rjmp __divmods8_done    ; signs equal -> trunc == floor
    tst  r25
    breq __divmods8_done    ; exact -> no correction
    dec  r24            ; floor: q -= 1
    add  r25, r17       ;        r += b
__divmods8_done:
    pop  r19
    pop  r17
    pop  r16
    ret

__divs8:
    rcall __divmods8
    ret                 ; quotient already in R24

__mods8:
    rcall __divmods8
    mov  r24, r25       ; remainder -> result register
    ret

; -----------------------------------------------------------------------------
; PyMCU AVR Math Runtime
; -----------------------------------------------------------------------------
;
; __mul32: Unsigned 32-bit Multiplication (low 32 bits of the product)
;   Input:  R23:R22:R25:R24 (a, MSB..LSB), R21:R20:R19:R18 (b, MSB..LSB)
;   Output: R23:R22:R25:R24 (low 32 bits of a*b)
;
; Byte positions (LSB first):
;   a: a0=R24, a1=R25, a2=R22, a3=R23
;   b: b0=R18, b1=R19, b2=R20, b3=R21
;
; Schoolbook 8x8->16 (MUL) partial products summed into r4:r5:r6:r7, keeping only the
; low four bytes (products that land entirely above byte 3 are dropped). MUL clobbers R1,
; so carry propagation uses a dedicated zero register R8 (cleared once) rather than R1.
; R4-R8 are saved/restored; R0/R1 are scratch (R1 restored to 0).
; -----------------------------------------------------------------------------

__mul32:
    push r4
    push r5
    push r6
    push r7
    push r8
    clr r4
    clr r5
    clr r6
    clr r7
    clr r8                 ; zero register for carry-only adds (R1 is busy with MUL)

    ; offset 0 -> bytes 0,1 (carry to 2,3)
    mul r24, r18           ; a0*b0
    add r4, r0
    adc r5, r1
    adc r6, r8
    adc r7, r8

    ; offset 1 -> bytes 1,2 (carry to 3)
    mul r24, r19           ; a0*b1
    add r5, r0
    adc r6, r1
    adc r7, r8
    mul r25, r18           ; a1*b0
    add r5, r0
    adc r6, r1
    adc r7, r8

    ; offset 2 -> bytes 2,3
    mul r24, r20           ; a0*b2
    add r6, r0
    adc r7, r1
    mul r25, r19           ; a1*b1
    add r6, r0
    adc r7, r1
    mul r22, r18           ; a2*b0
    add r6, r0
    adc r7, r1

    ; offset 3 -> byte 3 (low half only; high half overflows 32 bits)
    mul r24, r21           ; a0*b3
    add r7, r0
    mul r25, r20           ; a1*b2
    add r7, r0
    mul r22, r19           ; a2*b1
    add r7, r0
    mul r23, r18           ; a3*b0
    add r7, r0

    clr r1                 ; restore the zero register
    mov r24, r4            ; result -> output registers
    mov r25, r5
    mov r22, r6
    mov r23, r7
    pop r8
    pop r7
    pop r6
    pop r5
    pop r4
    ret


